// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address ownerBefore = c.owner();
        assertEq(ownerBefore, address(this));
        c.setOwner(alice);
        address ownerAfter = c.owner();
        assertTrue(ownerAfter != address(this));
    }
}
